int checks=0;
void check(bool b,const std::string&why){++checks;if(!b)throw std::runtime_error("CHECK FAILED: "+why);}
Result cmd(World&w,int actor,const std::string&verb,int target=0,int amount=1,int option=0,std::string text=""){return w.submit({actor,verb,target,amount,option,w.state().revision,text});}
void ok(Result r){check(r.ok,r.message);}
void reject(World&w,const Command&c,const std::string&reason){auto before=w.save();auto r=w.submit(c);check(!r.ok&&r.message.find(reason)!=std::string::npos,"Expected reject "+reason+"; got "+r.message);check(w.save()==before,"Reject must preserve all state");}
void deny(World&w,int id,std::string verb,int target,std::string reason,int amount=1,int option=0){reject(w,{id,verb,target,amount,option,w.state().revision,""},reason);}
void go(World&w,int id,int target){ok(cmd(w,id,"move",target));ok(w.advance(1));}
void finish(World&w,int id){int guard=0;while(person(w.state(),id).activity.kind!=ActivityKind::Idle){ok(w.advance(1));check(++guard<30,"Activity terminates");}}
